-- ONE statement. Run only at the documented step; do not also run master 02.
USE auxiliares;
ALTER TABLE FB_DOMICILIOS
 ADD VERIFICACION_CP_JSON JSON NULL,
 ADD CONSTRAINT FK_71_DOM_CP FOREIGN KEY (ID_PERSONA,ID_PERSONA_CP) REFERENCES FB_PERSONAS(ID_PERSONA,ID_PERSONA_CP),
 ADD CONSTRAINT FK_71_DOM_IDENTIDAD FOREIGN KEY (ID_CONSULTA,ID_PERSONA) REFERENCES FB_CIU_CONSULTAS_WEB(ID_CONSULTA,ID_PERSONA),
 ADD CONSTRAINT CHK_71_DOM_CP CHECK ((ID_DOMICILIO_CP IS NULL AND VERIFICACION_CP_JSON IS NULL) OR (ID_DOMICILIO_CP>0 AND ID_PERSONA_CP IS NOT NULL AND VERIFICACION_CP_JSON IS NOT NULL AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.addressId'))=CAST(ID_DOMICILIO_CP AS CHAR) AND JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.personId'))=CAST(ID_PERSONA_CP AS CHAR) AND JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.source'))='institutional',0))),
 ADD CONSTRAINT CHK_71_DOM_NO_VACIO CHECK (CHAR_LENGTH(TRIM(CONCAT_WS('',CALLE,NUMERO,BARRIO,LOCALIDAD,DEPARTAMENTO,CODIGO_POSTAL,PH,BLOCK,DEPTO,PUERTA,DOMICILIO_COMPLETO,REFERENCIA,SECTOR,MANZANA,LOTE)))>0);
